/**
 * Find local media URLs in a serialized snapshot.
 *
 * Snapshot HTML stores media metadata as HTML-escaped JSON. A delimiter based
 * on whitespace or quotes therefore consumes `&quot;...` after the URL and
 * turns one valid blob URL into a bogus fetch target. Blob URLs generated by
 * browsers have an origin followed by one opaque UUID path segment, so keep
 * extraction bounded to that native shape.
 */
const SNAPSHOT_BLOB_URL = /blob:https?:\/\/(?:[A-Za-z0-9.-]+|\[[0-9A-Fa-f:.]+\])(?::\d+)?\/[A-Za-z0-9._~-]+/g;

export function snapshotBlobUrls(serialized: string): string[] {
  return [...new Set(serialized.match(SNAPSHOT_BLOB_URL) ?? [])];
}
